+@page "/recipes/{CuisineId:int}"
+@rendermode InteractiveServer
+@implements IDisposable
+@using sv_0934a93efdc7425e864528d4ad2d847a.Models
+@using sv_0934a93efdc7425e864528d4ad2d847a.Services
+@inject IRecipeService RecipeService
+@inject ILogger<Recipes> Logger
+@inject NavigationManager Navigation
+
+<PageTitle>Recipes</PageTitle>
+
+<h1>Recipes</h1>
+
+<div class="mb-3">
+    <label class="form-label fw-bold">Sort by:</label>
+    <div class="btn-group ms-2" role="group">
+        <button class="btn btn-sm @(currentSort == "newest" ? "btn-primary" : "btn-outline-primary")"
+                @onclick='() => SetSort("newest")'>Newest</button>
+        <button class="btn btn-sm @(currentSort == "popular" ? "btn-primary" : "btn-outline-primary")"
+                @onclick='() => SetSort("popular")'>Popular</button>
+    </div>
+</div>
+
+@if (errorMessage is not null)
+{
+    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
+        <span>@errorMessage</span>
+        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
+    </div>
+}
+
+@if (isLoading && recipes is null)
+{
+    <div class="d-flex align-items-center gap-2 my-4">
+        <div class="spinner-border spinner-border-sm" role="status"></div>
+        <span>Loading recipes…</span>
+    </div>
+}
+else if (recipes is not null)
+{
+    @if (isLoading)
+    {
+        <div class="d-flex align-items-center gap-2 mb-3 text-muted">
+            <div class="spinner-border spinner-border-sm" role="status"></div>
+            <small>Refreshing…</small>
+        </div>
+    }
+
+    <div class="row row-cols-1 row-cols-md-3 g-4">
+        @foreach (var recipe in SortedRecipes)
+        {
+            <div class="col">
+                <div class="card h-100">
+                    <div class="card-body">
+                        <h5 class="card-title">@recipe.Title</h5>
+                        <p class="card-text">@recipe.Description</p>
+                    </div>
+                    <div class="card-footer text-body-secondary">
+                        ⏱ @recipe.PrepTimeMinutes min
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+
+    @if (recipes.Count == 0 && errorMessage is null)
+    {
+        <p class="text-muted">No recipes found for this cuisine.</p>
+    }
+}
+
+@code {
+    [Parameter]
+    public int CuisineId { get; set; }
+
+    [SupplyParameterFromQuery(Name = "sort")]
+    public string? Sort { get; set; }
+
+    private List<Recipe>? recipes;
+    private bool isLoading;
+    private string? errorMessage;
+    private string currentSort = "newest";
+    private int loadedCuisineId;
+
+    private CancellationTokenSource? loadCts;
+    private readonly CancellationTokenSource disposalCts = new();
+
+    private IEnumerable<Recipe> SortedRecipes =>
+        recipes is null
+            ? Enumerable.Empty<Recipe>()
+            : currentSort == "popular"
+                ? recipes.OrderByDescending(r => r.PrepTimeMinutes)
+                : recipes.OrderByDescending(r => r.Id);
+
+    protected override async Task OnParametersSetAsync()
+    {
+        var sortValue = string.IsNullOrWhiteSpace(Sort) ? "newest" : Sort.ToLowerInvariant();
+        if (sortValue is not ("newest" or "popular"))
+        {
+            sortValue = "newest";
+        }
+        currentSort = sortValue;
+
+        if (CuisineId != loadedCuisineId)
+        {
+            await LoadRecipesAsync();
+        }
+    }
+
+    private async Task LoadRecipesAsync()
+    {
+        // Cancel any in-flight load
+        if (loadCts is not null)
+        {
+            await loadCts.CancelAsync();
+            loadCts.Dispose();
+        }
+
+        loadCts = CancellationTokenSource.CreateLinkedTokenSource(disposalCts.Token);
+        var cts = loadCts;
+        var cuisineId = CuisineId;
+
+        isLoading = true;
+        errorMessage = null;
+
+        try
+        {
+            var result = await RecipeService.GetByCuisineAsync(cuisineId, cts.Token);
+
+            // Only apply if this is still the most recent request
+            if (cts.Token.IsCancellationRequested)
+            {
+                return;
+            }
+
+            recipes = result;
+            loadedCuisineId = cuisineId;
+        }
+        catch (OperationCanceledException) when (disposalCts.IsCancellationRequested)
+        {
+            // Component is being disposed — do nothing
+        }
+        catch (OperationCanceledException)
+        {
+            // Superseded by a newer load — do nothing
+        }
+        catch (TimeoutException ex)
+        {
+            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
+            errorMessage = "The request timed out. Please check your connection and try again.";
+        }
+        catch (Exception ex)
+        {
+            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
+            errorMessage = "Something went wrong while loading recipes. Please try again.";
+        }
+        finally
+        {
+            if (!disposalCts.IsCancellationRequested)
+            {
+                isLoading = false;
+            }
+        }
+    }
+
+    private async Task RetryAsync()
+    {
+        loadedCuisineId = 0;
+        await LoadRecipesAsync();
+    }
+
+    private void SetSort(string sort)
+    {
+        currentSort = sort;
+        Navigation.NavigateTo(
+            Navigation.GetUriWithQueryParameter("sort", sort),
+            replace: true);
+    }
+
+    public void Dispose()
+    {
+        disposalCts.Cancel();
+        disposalCts.Dispose();
+        loadCts?.Dispose();
+    }
+}
+

